public final class CircularRevealSmoke {
 static void check(boolean v,String m){if(!v)throw new AssertionError(m);}
 static long time;
 static void frame(long delta){time=Math.max(time,SystemClock.uptimeMillis())+delta;Choreographer.getInstance().shirazDoFrame(time*1000000,null);}
 static Bitmap draw(View v){Bitmap b=Bitmap.createBitmap(40,40,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);v.shirazDrawWithAlpha(c);Paint p=new Paint();p.setColor(0xff00ff00);c.drawRect(0,0,2,2,p);check(b.getPixel(0,0)==0xff00ff00,"clip leaked to caller");return b;}
 public static void main(String[] args){Looper.prepareMainLooper();try{
 time=SystemClock.uptimeMillis();View v=new View(new android.content.ContextWrapper(null));v.layout(0,0,40,40);v.setBackgroundColor(0xffff0000);
 Animator a=ViewAnimationUtils.createCircularReveal(v,20,20,0,20);a.setInterpolator(null);a.setDuration(100);a.setStartDelay(20);
 StringBuilder e=new StringBuilder();a.addListener(new AnimatorListenerAdapter(){public void onAnimationStart(Animator a){e.append('S');}public void onAnimationCancel(Animator a){e.append('C');}public void onAnimationEnd(Animator a){e.append('E');}});
 a.start();check(draw(v).getPixel(5,5)==0xffff0000,"delay must not clip");frame(30);check(draw(v).getPixel(20,20)==0,"zero radius");frame(50);Bitmap b=draw(v);check(b.getPixel(20,20)==0xffff0000&&b.getPixel(5,5)==0,"intermediate circular clip");a.cancel();check(e.toString().equals("SCE"),"cancel lifecycle");check(draw(v).getPixel(5,5)==0xffff0000,"cancel removes clip");
 try{a.start();throw new AssertionError("reused reveal");}catch(IllegalStateException expected){}
 Animator end=ViewAnimationUtils.createCircularReveal(v,20,20,20,0);end.start();end.end();check(draw(v).getPixel(5,5)==0xffff0000,"end clears clip");
 Animator neverStarted=ViewAnimationUtils.createCircularReveal(v,20,20,0,20);final int[] ends={0};neverStarted.addListener(new AnimatorListenerAdapter(){public void onAnimationEnd(Animator a){ends[0]++;}});neverStarted.end();neverStarted.end();check(ends[0]==1,"end is idempotent");try{neverStarted.start();throw new AssertionError("end then start");}catch(IllegalStateException expected){}
 Animator natural=ViewAnimationUtils.createCircularReveal(v,20,20,0,20);natural.setDuration(10);natural.start();frame(1);frame(10);check(!natural.isRunning()&&draw(v).getPixel(5,5)==0xffff0000,"natural completion clears clip");
 Animator bad=ViewAnimationUtils.createCircularReveal(v,20,20,0,20);bad.setStartDelay(1);bad.addListener(new AnimatorListenerAdapter(){public void onAnimationStart(Animator a){throw new IllegalStateException("callback");}});bad.start();try{frame(10);throw new AssertionError("callback swallowed");}catch(IllegalStateException expected){}check(draw(v).getPixel(5,5)==0xffff0000,"exception clears state");
 v.setClipBounds(new Rect(10,10,30,30));Animator clipped=ViewAnimationUtils.createCircularReveal(v,20,20,15,15);clipped.start();b=draw(v);check(b.getPixel(20,20)==0xffff0000&&b.getPixel(8,20)==0,"rect intersection");clipped.cancel();
 v.setClipBounds(null);v.setOutlineProvider(new ViewOutlineProvider(){public void getOutline(View view,Outline out){out.setRect(0,0,5,5);}});v.setClipToOutline(true);
 Animator priority=ViewAnimationUtils.createCircularReveal(v,20,20,10,10);priority.start();check(draw(v).getPixel(20,20)==0xffff0000,"reveal overrides outline");priority.cancel();check(draw(v).getPixel(20,20)==0,"outline restored");
 for(float invalid:new float[]{-1,Float.NaN,Float.POSITIVE_INFINITY})try{ViewAnimationUtils.createCircularReveal(v,0,0,invalid,1);throw new AssertionError("invalid radius");}catch(IllegalArgumentException expected){}
 ObjectAnimator sx=ObjectAnimator.ofFloat(v,View.SCALE_X,1,.5f);sx.start();sx.end();check(v.getScaleX()==.5f&&View.SCALE_X.get(v)==.5f,"scale X property binding");ObjectAnimator sy=ObjectAnimator.ofFloat(v,View.SCALE_Y,1,.25f);sy.start();sy.end();check(v.getScaleY()==.25f&&View.SCALE_Y.get(v)==.25f,"scale Y property binding");
 android.widget.FrameLayout group=new android.widget.FrameLayout(new android.content.ContextWrapper(null));View scaled=new View(new android.content.ContextWrapper(null));scaled.setBackgroundColor(0xffff0000);group.addView(scaled,new android.widget.FrameLayout.LayoutParams(40,40));group.layout(0,0,40,40);scaled.layout(0,0,40,40);
 Animator scaledReveal=ViewAnimationUtils.createCircularReveal(scaled,20,20,30,30);scaledReveal.start();scaled.setScaleX(0);check(draw(group).getPixel(20,20)==0,"zero scale has no ink");scaled.setScaleX(.5f);scaled.setScaleY(.5f);b=draw(group);check(b.getPixel(20,20)==0xffff0000&&b.getPixel(5,20)==0,"center pivot scale pixels");
 final float[] hit={-1,-1};scaled.setOnTouchListener(new View.OnTouchListener(){public boolean onTouch(View v,MotionEvent event){hit[0]=event.getX();hit[1]=event.getY();return true;}});MotionEvent event=MotionEvent.obtain(0,0,MotionEvent.ACTION_DOWN,15,15,0);check(group.dispatchTouchEvent(event)&&Math.abs(hit[0]-10)<.01&&Math.abs(hit[1]-10)<.01,"inverse scaled input");event.recycle();event=MotionEvent.obtain(0,1,MotionEvent.ACTION_UP,15,15,0);group.dispatchTouchEvent(event);event.recycle();scaled.setScaleX(-.5f);event=MotionEvent.obtain(2,2,MotionEvent.ACTION_DOWN,15,15,0);check(group.dispatchTouchEvent(event)&&Math.abs(hit[0]-30)<.01,"negative scale input");event.recycle();event=MotionEvent.obtain(2,3,MotionEvent.ACTION_UP,15,15,0);group.dispatchTouchEvent(event);event.recycle();scaled.setScaleX(0);event=MotionEvent.obtain(4,4,MotionEvent.ACTION_DOWN,20,20,0);check(!group.dispatchTouchEvent(event),"collapsed view cannot be hit");event.recycle();scaledReveal.cancel();
 scaled.setScaleX(1);scaled.setScaleY(1);scaled.setRotationY(180);final boolean[] canceled={false};scaled.setOnTouchListener(new View.OnTouchListener(){public boolean onTouch(View v,MotionEvent event){MotionEvent.PointerCoords pc=new MotionEvent.PointerCoords();event.getPointerCoords(0,pc);check(Float.isFinite(pc.x)&&Float.isFinite(pc.y),"nonfinite pointer dispatched");if(event.getAction()==MotionEvent.ACTION_DOWN)check(pc.orientation==-.3f,"mirror orientation");if(event.getAction()==MotionEvent.ACTION_CANCEL)canceled[0]=true;return true;}});
 MotionEvent.PointerProperties prop=new MotionEvent.PointerProperties();prop.id=0;MotionEvent.PointerCoords point=new MotionEvent.PointerCoords();point.x=15;point.y=15;point.orientation=.3f;
 event=MotionEvent.obtain(5,5,MotionEvent.ACTION_DOWN,1,new MotionEvent.PointerProperties[]{prop},new MotionEvent.PointerCoords[]{point},0,0,1,1,0,0,0,0);group.dispatchTouchEvent(event);event.recycle();scaled.setScaleX(Float.MIN_VALUE);event=MotionEvent.obtain(5,6,MotionEvent.ACTION_MOVE,15,15,0);group.dispatchTouchEvent(event);event.recycle();check(canceled[0],"unrepresentable inverse cancels capture");
 android.widget.TextView label=new android.widget.TextView(new android.content.ContextWrapper(null){public android.content.res.Resources getResources(){return android.content.res.Resources.getSystem();}});label.setText("Configure map حافظ");label.setTextSize(12);group.removeAllViews();group.addView(label,new android.widget.FrameLayout.LayoutParams(40,40));label.layout(0,0,40,40);label.setScaleX(.4f);label.setScaleY(.4f);Animator textReveal=ViewAnimationUtils.createCircularReveal(label,20,20,30,30);textReveal.start();Bitmap labelPixels=draw(group);boolean labelInk=false;for(int yy=3;yy<40;yy++)for(int xx=3;xx<40;xx++)labelInk|=labelPixels.getPixel(xx,yy)!=0;check(labelInk,"intermediate dashboard scale renders text");textReveal.end();
 System.out.println("CIRCULAR_REVEAL_OK");
 }finally{Looper.shirazShutdownMain();}}
}
